template <typename scalar_t>
__global__ void sum_reduce_kernel(const scalar_t* __restrict__ input,
                                  scalar_t* __restrict__ output,
                                  const int64_t dim0,
                                  const int64_t dim1,
                                  const int64_t dim2,
                                  const int reduce_dim) {
