    const int64_t outer_idx = blockIdx.x;
    int64_t reduce_size = 0;
    int64_t stride_reduce = 0;
    int64_t offset_base = 0;   // offset of the first element of the reduction slice
    int64_t out_offset   = 0;   // linear offset where the reduced result is stored

    // Compute coordinates of the slice that this block will reduce.
    if (reduce_dim == 0) {
        // outer dimensions: dim1 (i1) and dim2 (i2)
        const int64_t i1 = outer_idx / dim2;
        const int64_t i2 = outer_idx % dim2;
        reduce_size   = dim0;
        stride_reduce = dim1 * dim2;          // stride of dim0 in a contiguous tensor
        offset_base   = i1 * dim2 + i2;       // index when dim0 == 0
        out_offset    = i1 * dim2 + i2;       // output has dim0 == 0
    } else if (reduce_dim == 1) {
        // outer dimensions: dim0 (i0) and dim2 (i2)
        const int64_t i0 = outer_idx / dim2;
        const int64_t i2 = outer_idx % dim2;
        reduce_size   = dim1;
        stride_reduce = dim2;                  // stride of dim1
        offset_base   = i0 * dim1 * dim2 + i2; // dim1 == 0
        out_offset    = i0 * dim2 + i2;        // output has dim1 == 0
    } else { // reduce_dim == 2
        // outer dimensions: dim0 (i0) and dim1 (i1)
        const int64_t i0 = outer_idx / dim1;
        const int64_t i1 = outer_idx % dim1;
        reduce_size   = dim2;
        stride_reduce = 1;                     // stride of dim2
        offset_base   = i0 * dim1 * dim2 + i1 * dim2; // dim2 == 0
        out_offset    = i0 * dim1 + i1;               // output has dim2 == 0
    }

    // Each thread sums a strided subset of the reduction dimension.
    float thread_sum = 0.0f;
    for (int64_t r = threadIdx.x; r < reduce_size; r += blockDim.x) {
        const int64_t idx = offset_base + r * stride_reduce;
        thread_sum += static_cast<float>(input[idx]);
    }

    // Block‑wide reduction using shared memory.
    __shared__ float shmem[256];          // maximum block size we launch
    shmem[threadIdx.x] = thread_sum;
    __syncthreads();

    // Parallel reduction in shared memory.
    for (int offset = blockDim.x / 2; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            shmem[threadIdx.x] += shmem[threadIdx.x + offset];
        }
        __syncthreads();
    }

    // Write the final sum for this slice.
    if (threadIdx.x == 0) {
        output[out_offset] = static_cast<scalar_t>(shmem[0]);
    }
}

