    // Input must be 3‑D and contiguous.
    TORCH_CHECK(input.dim() == 3, "Only 3‑D tensors are supported.");
    TORCH_CHECK(input.is_contiguous(), "Input tensor must be contiguous.");
    TORCH_CHECK(input.dtype() == torch::kHalf, "Input must be float16.");

    const int64_t dim0 = input.size(0);
    const int64_t dim1 = input.size(1);
    const int64_t dim2 = input.size(2);

    // Output shape: same as input but reduced dimension has size 1.
    std::vector<int64_t> out_sizes = {dim0, dim1, dim2};
    out_sizes[reduce_dim] = 1;
    auto options = input.options();
    torch::Tensor output = torch::empty(out_sizes, options);

    // Number of output elements (product of non‑reduced dims).
